<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $labels = ['competitions' => 'Competições', 'sponsorship' => 'Patrocínio', 'transfers' => 'Transferências', 'documents' => 'Documentos', 'result_error' => 'Erro em resultados', 'other' => 'Outro']; ?>
<section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Relacionamento</p><h1>Contatos recebidos</h1><p class="muted">Solicitações enviadas pelo portal público. Dados de contato ficam somente neste painel.</p></div></div><?php if (!empty($message)): ?><p class="success" role="status"><?= $e($message) ?></p><?php endif; ?><div class="contact-list"><?php foreach ($items as $item): ?><article class="panel contact-item"><header><div><span class="status status-<?= $e($item['status']) ?>"><?= $e($item['status']) ?></span><h2><?= $e($item['name']) ?></h2><p><?= $e($item['email']) ?><?= $item['phone'] ? ' · ' . $e($item['phone']) : '' ?></p></div><small><?= $e($item['created_at']) ?></small></header><dl class="summary-list"><dt>Assunto</dt><dd><?= $e($labels[$item['subject']] ?? $item['subject']) ?></dd><dt>Campeonato</dt><dd><?= $e($item['championship_name'] ?: 'Geral') ?></dd><dt>Mensagem</dt><dd><?= nl2br($e($item['message'])) ?></dd></dl><form method="post" action="<?= $e(App\Core\Config::url('/admin/contatos/' . $item['id'])) ?>" class="inline-form"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><label>Situação <select name="status"><?php foreach (['new' => 'Novo', 'in_progress' => 'Em andamento', 'resolved' => 'Resolvido', 'archived' => 'Arquivado'] as $key => $label): ?><option value="<?= $key ?>" <?= $item['status'] === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><button type="submit">Salvar situação</button></form></article><?php endforeach; ?><?php if (!$items): ?><div class="empty-state"><strong>Nenhum contato recebido.</strong><p>As novas mensagens do portal aparecerão aqui e nas notificações.</p></div><?php endif; ?></div></section>
